pair A=(-0.56,4.56), B=(-2.96,-0.22), C=(5.22,0.), D=(0.12360457548166057,-0.13706686960807268), F=(-1.5758595788389178,2.5367463388124882), I=(0.07397155040430481,1.7083792446317907); 
